def add_AgentServiceServicer_to_server(servicer, server):
    rpc_method_handlers = {
            'RequestProposal': grpc.unary_unary_rpc_method_handler(
                    servicer.RequestProposal,
                    request_deserializer=cambrian__pb2.ProposalRequest.FromString,
                    response_serializer=cambrian__pb2.ProposalResponse.SerializeToString,
            ),
            'Execute': grpc.unary_unary_rpc_method_handler(
                    servicer.Execute,
                    request_deserializer=cambrian__pb2.Handoff.FromString,
                    response_serializer=cambrian__pb2.Handoff.SerializeToString,
            ),
            'VerifyOutput': grpc.unary_unary_rpc_method_handler(
                    servicer.VerifyOutput,
                    request_deserializer=cambrian__pb2.VerifyRequest.FromString,
                    response_serializer=cambrian__pb2.VerifyResponse.SerializeToString,
            ),
    }
    generic_handler = grpc.method_handlers_generic_handler(
            'cambrian.AgentService', rpc_method_handlers)
    server.add_generic_rpc_handlers((generic_handler,))
    server.add_registered_method_handlers('cambrian.AgentService', rpc_method_handlers)


